(2501, 'Exodus 36:9', 'Exodus', 36, 9, '&nbsp;ټولې پړدې په يو ناپ وې، هره يوه څوارلس ګزه اوږده او دوه ګزه پلنه وه.', NULL, '&nbsp;ټولې پړدې په يو ناپ وې، هره يوه څوارلس ګزه اوږده او دوه ګزه پلنه وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2502, 'Exodus 36:10', 'Exodus', 36, 10, '&nbsp;هغوئ پينځۀ پړدې يو ځائ وګنډلې او هغه نورې پينځۀ يې هم يو ځائ وګنډلې.', NULL, '&nbsp;هغوئ پينځۀ پړدې يو ځائ وګنډلې او هغه نورې پينځۀ يې هم يو ځائ وګنډلې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2503, 'Exodus 36:11', 'Exodus', 36, 11, '&nbsp;هغوئ په هره جوړه کښې د پړدې په بهرنۍ غاړه د آسمانى رنګ د کپړې کَړۍ جوړې کړې.', NULL, '&nbsp;هغوئ په هره جوړه کښې د پړدې په بهرنۍ غاړه د آسمانى رنګ د کپړې کَړۍ جوړې کړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2504, 'Exodus 36:12', 'Exodus', 36, 12, '&nbsp;هغوئ د وړومبۍ جوړې په وړومبۍ پړده پنځوس کَړۍ او پنځوس کَړۍ د دوېمې جوړې په آخرى پړده جوړې کړې چې دا کَړۍ يو بل ته مخامخ وې.', NULL, '&nbsp;هغوئ د وړومبۍ جوړې په وړومبۍ پړده پنځوس کَړۍ او پنځوس کَړۍ د دوېمې جوړې په آخرى پړده جوړې کړې چې دا کَړۍ يو بل ته مخامخ وې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2505, 'Exodus 36:13', 'Exodus', 36, 13, '&nbsp;پنځوس د سرو زرو کُنډې يې جوړې کړې او هغه پړدې يې د يوې بلې سره مِلاو کړې نو داسې ټوله مقدسه خېمه يو ځائ شوه.', NULL, '&nbsp;پنځوس د سرو زرو کُنډې يې جوړې کړې او هغه پړدې يې د يوې بلې سره مِلاو کړې نو داسې ټوله مقدسه خېمه يو ځائ شوه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2506, 'Exodus 36:14', 'Exodus', 36, 14, '&nbsp;بيا هغوئ د چېلو د وړۍ نه جوړې شوې يوولس پړدې واخستلې او د خېمې پټولو دپاره يې يوه پړده ترې نه جوړه کړه.', NULL, '&nbsp;بيا هغوئ د چېلو د وړۍ نه جوړې شوې يوولس پړدې واخستلې او د خېمې پټولو دپاره يې يوه پړده ترې نه جوړه کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2507, 'Exodus 36:15', 'Exodus', 36, 15, '&nbsp;هغوئ دا ټولې په يو ناپ جوړې کړې چې پينځلس ګزه اوږدې او دوه ګزه پلنې وې.', NULL, '&nbsp;هغوئ دا ټولې په يو ناپ جوړې کړې چې پينځلس ګزه اوږدې او دوه ګزه پلنې وې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2508, 'Exodus 36:16', 'Exodus', 36, 16, '&nbsp;هغوئ پينځۀ پړدې يو ځائ وګنډلې او هغه نورې شپږ يې هم يو ځائ وګنډلې.', NULL, '&nbsp;هغوئ پينځۀ پړدې يو ځائ وګنډلې او هغه نورې شپږ يې هم يو ځائ وګنډلې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2509, 'Exodus 36:17', 'Exodus', 36, 17, '&nbsp;د يوې جوړې د آخرى پړدې په غاړه يې پنځوس کَړۍ جوړې کړې او د هغه بلې جوړې په غاړه يې هم پنځوس کَړۍ جوړې کړې.', NULL, '&nbsp;د يوې جوړې د آخرى پړدې په غاړه يې پنځوس کَړۍ جوړې کړې او د هغه بلې جوړې په غاړه يې هم پنځوس کَړۍ جوړې کړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2510, 'Exodus 36:18', 'Exodus', 36, 18, '&nbsp;هغوئ د زېړو پنځوس کُنډې جوړې کړې او هغه يې په کړو کښې واچولې چې هغه دوه جوړې يې سره مِلاو کړې نو داسې خېمه وتړلے شوه.', NULL, '&nbsp;هغوئ د زېړو پنځوس کُنډې جوړې کړې او هغه يې په کړو کښې واچولې چې هغه دوه جوړې يې سره مِلاو کړې نو داسې خېمه وتړلے شوه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2511, 'Exodus 36:19', 'Exodus', 36, 19, '&nbsp;هغوئ دوه نورې پړدې هم جوړې کړې، يوه پړده يې د ګډو د څرمنې نه چې سور رنګ ورکړے شوے وو او بله يې د ښې څرمنې نه جوړه کړه، چې د پاس نه پرې خېمه پټه کړے شى.', NULL, '&nbsp;هغوئ دوه نورې پړدې هم جوړې کړې، يوه پړده يې د ګډو د څرمنې نه چې سور رنګ ورکړے شوے وو او بله يې د ښې څرمنې نه جوړه کړه، چې د پاس نه پرې خېمه پټه کړے شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2512, 'Exodus 36:20', 'Exodus', 36, 20, '&nbsp;هغوئ د خېمې د ودرولو دپاره د کيکر د لرګى چوکاټونه جوړ کړل.', NULL, '&nbsp;هغوئ د خېمې د ودرولو دپاره د کيکر د لرګى چوکاټونه جوړ کړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2513, 'Exodus 36:21', 'Exodus', 36, 21, '&nbsp;هر يو چوکاټ پينځلس فټه اوږد وو او اوويشت اِنچې پلن وو،', NULL, '&nbsp;هر يو چوکاټ پينځلس فټه اوږد وو او اوويشت اِنچې پلن وو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2514, 'Exodus 36:22', 'Exodus', 36, 22, '&nbsp;سره د دوه يو شان تختو، چې دا چوکاټونه په خپلو کښې ونښلوى. د ټولو چوکاټونو دا تختې وې.', NULL, '&nbsp;سره د دوه يو شان تختو، چې دا چوکاټونه په خپلو کښې ونښلوى. د ټولو چوکاټونو دا تختې وې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2515, 'Exodus 36:23', 'Exodus', 36, 23, '&nbsp;هغوئ د خېمې جنوبى طرف دپاره شل چوکاټونه جوړ کړل', NULL, '&nbsp;هغوئ د خېمې جنوبى طرف دپاره شل چوکاټونه جوړ کړل', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2516, 'Exodus 36:24', 'Exodus', 36, 24, '&nbsp;او څلوېښت د سپينو زرو پښې چې ورلاندې شى، د هر يو چوکاټ لاندې دوه دوه پښې چې هغه دوه وړاندينۍ حِصې يې نيولې وې.', NULL, '&nbsp;او څلوېښت د سپينو زرو پښې چې ورلاندې شى، د هر يو چوکاټ لاندې دوه دوه پښې چې هغه دوه وړاندينۍ حِصې يې نيولې وې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2517, 'Exodus 36:25', 'Exodus', 36, 25, '&nbsp;هغوئ د خېمې شمالى طرف دپاره هم شل چوکاټونه جوړ کړل', NULL, '&nbsp;هغوئ د خېمې شمالى طرف دپاره هم شل چوکاټونه جوړ کړل', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2518, 'Exodus 36:26', 'Exodus', 36, 26, '&nbsp;او څلوېښت د سپينو زرو پښې، چې د هر يو چوکاټ لاندې دوه دوه وې.', NULL, '&nbsp;او څلوېښت د سپينو زرو پښې، چې د هر يو چوکاټ لاندې دوه دوه وې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2519, 'Exodus 36:27', 'Exodus', 36, 27, '&nbsp;د نمرپرېواتۀ په طرف خېمې شا ته هغوئ شپږ چوکاټونه جوړ کړل', NULL, '&nbsp;د نمرپرېواتۀ په طرف خېمې شا ته هغوئ شپږ چوکاټونه جوړ کړل', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2520, 'Exodus 36:28', 'Exodus', 36, 28, '&nbsp;او دوه چوکاټونه يې د خېمې د ګوټونو دپاره هم جوړ کړل.', NULL, '&nbsp;او دوه چوکاټونه يې د خېمې د ګوټونو دپاره هم جوړ کړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2521, 'Exodus 36:29', 'Exodus', 36, 29, '&nbsp;د ګوټونو دا چوکاټونه په بېخ کښې مِلاو وُو او د لاندې نه واخله تر سر پورې خپلو کښې انښتى وُو. دا دوه چوکاټونه هم د ګوټونو د دوه چوکاټونو په شان جوړ شوى وُو.', NULL, '&nbsp;د ګوټونو دا چوکاټونه په بېخ کښې مِلاو وُو او د لاندې نه واخله تر سر پورې خپلو کښې انښتى وُو. دا دوه چوکاټونه هم د ګوټونو د دوه چوکاټونو په شان جوړ شوى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2522, 'Exodus 36:30', 'Exodus', 36, 30, '&nbsp;نو اتۀ چوکاټونه او شپاړس د سپينو زرو پښې وې، چې د هر چوکاټ لاندې دوه دوه وې.', NULL, '&nbsp;نو اتۀ چوکاټونه او شپاړس د سپينو زرو پښې وې، چې د هر چوکاټ لاندې دوه دوه وې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2523, 'Exodus 36:31', 'Exodus', 36, 31, '&nbsp;هغوئ د کيکر د لرګى نه پينځلس لاړى جوړ کړل، پينځۀ د خېمې د هغو چوکاټونو دپاره چې په يو طرف باندې وُو،', NULL, '&nbsp;هغوئ د کيکر د لرګى نه پينځلس لاړى جوړ کړل، پينځۀ د خېمې د هغو چوکاټونو دپاره چې په يو طرف باندې وُو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2524, 'Exodus 36:32', 'Exodus', 36, 32, '&nbsp;پينځۀ د هغو چوکاټونو دپاره چې په بل طرف باندې وُو او پينځۀ د هغه چوکاټونو دپاره چې نمرخاتۀ په طرف شا ته په آخر سر کښې وُو.', NULL, '&nbsp;پينځۀ د هغو چوکاټونو دپاره چې په بل طرف باندې وُو او پينځۀ د هغه چوکاټونو دپاره چې نمرخاتۀ په طرف شا ته په آخر سر کښې وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2525, 'Exodus 36:33', 'Exodus', 36, 33, '&nbsp;تير د يو سر نه تر بل سره پورې پوره رسېدلے وو.', NULL, '&nbsp;تير د يو سر نه تر بل سره پورې پوره رسېدلے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2526, 'Exodus 36:34', 'Exodus', 36, 34, '&nbsp;هغوئ په چوکاټونو د سرو زرو پترى خېژولى وُو او د سرو زرو کَړۍ يې ورله جوړې کړې وې چې لاړى ونيسى، په لاړو باندې هم د سرو زرو پترى خېژولے شوى وُو.', NULL, '&nbsp;هغوئ په چوکاټونو د سرو زرو پترى خېژولى وُو او د سرو زرو کَړۍ يې ورله جوړې کړې وې چې لاړى ونيسى، په لاړو باندې هم د سرو زرو پترى خېژولے شوى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2527, 'Exodus 36:35', 'Exodus', 36, 35, '&nbsp;هغوئ د کتان نه يوه پړده جوړه کړه چې د آسمانى، کاسنى او د سور رنګ وړۍ نه تياره شوې وه او په دې باندې يې په ګُلکارۍ کښې د وزرو والا مخلوق جوړ کړے وو.', NULL, '&nbsp;هغوئ د کتان نه يوه پړده جوړه کړه چې د آسمانى، کاسنى او د سور رنګ وړۍ نه تياره شوې وه او په دې باندې يې په ګُلکارۍ کښې د وزرو والا مخلوق جوړ کړے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2528, 'Exodus 36:36', 'Exodus', 36, 36, '&nbsp;هغوئ د کيکر د لرګى نه څلور ستنې جوړې کړې چې پړده په کښې په کُنډو کښې راځوړنده شى، په دې ستنو باندې د سرو زرو پترى خېژولے شوى وُو. بيا هغوئ څلور د سپينو زرو پښې ورله جوړې کړې چې ستنې ونيسى.', NULL, '&nbsp;هغوئ د کيکر د لرګى نه څلور ستنې جوړې کړې چې پړده په کښې په کُنډو کښې راځوړنده شى، په دې ستنو باندې د سرو زرو پترى خېژولے شوى وُو. بيا هغوئ څلور د سپينو زرو پښې ورله جوړې کړې چې ستنې ونيسى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2529, 'Exodus 36:37', 'Exodus', 36, 37, '&nbsp;هغوئ د خېمې د ننوتلو دروازې دپاره د کتان نه يوه پړده جوړه کړه چې د آسمانى، کاسنى او د سور رنګ وړۍ نه تياره شوې وه او چې په ګُلکارۍ باندې ښائسته کړے شوې وه.', NULL, '&nbsp;هغوئ د خېمې د ننوتلو دروازې دپاره د کتان نه يوه پړده جوړه کړه چې د آسمانى، کاسنى او د سور رنګ وړۍ نه تياره شوې وه او چې په ګُلکارۍ باندې ښائسته کړے شوې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2530, 'Exodus 36:38', 'Exodus', 36, 38, '&nbsp;د دې پړدې دپاره هغوئ پينځۀ ستنې جوړې کړې چې کُنډې په کښې لګېدلې وې، د دې په سرونو او سيخونو د سرو زرو پترى خېژولے شوى وُو او د دې ستنو دپاره يې پينځۀ د زېړو پښې جوړې کړې.', NULL, '&nbsp;د دې پړدې دپاره هغوئ پينځۀ ستنې جوړې کړې چې کُنډې په کښې لګېدلې وې، د دې په سرونو او سيخونو د سرو زرو پترى خېژولے شوى وُو او د دې ستنو دپاره يې پينځۀ د زېړو پښې جوړې کړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
(2531, 'Exodus 37:1', 'Exodus', 37, 1, '&nbsp;بضلى‌اېل د کيکر د لرګى نه د لوظ صندوق جوړ کړو، چې پينځۀ څلوېښت اِنچۍ اوږد وو او اوويشت اِنچۍ پلن او اوويشت اِنچۍ لوړ وو.', NULL, '&nbsp;بضلى‌اېل د کيکر د لرګى نه د لوظ صندوق جوړ کړو، چې پينځۀ څلوېښت اِنچۍ اوږد وو او اوويشت اِنچۍ پلن او اوويشت اِنچۍ لوړ وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
