(2575, 'Exodus 38:18', 'Exodus', 38, 18, '&nbsp;د دربار د دروازې پړده د مهينې لټې نه جوړه وه چې د آسمانى رنګ، کاسنى او د سور رنګ وړۍ نه تياره شوې وه. او په ګُلکارۍ ښائسته کړے شوې وه. دا د دربار د پړدو په شان، لس ګزه اوږده او دوه نيم ګزه اوچته وه.', NULL, '&nbsp;د دربار د دروازې پړده د مهينې لټې نه جوړه وه چې د آسمانى رنګ، کاسنى او د سور رنګ وړۍ نه تياره شوې وه. او په ګُلکارۍ ښائسته کړے شوې وه. دا د دربار د پړدو په شان، لس ګزه اوږده او دوه نيم ګزه اوچته وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756483, 1761756483),
